int pow(int x, int n) 
{ 
    int y; 
    if( n == 0) 
        return 1; 
    y = pow(x, n/2); 
    if (n%2 == 0) 
        return y*y; 
    else
        return x*y*y; 
} 
int main() 
{ 
    int x = 6; 
    int n = 3; 
  
    printf("The output for x^n, where x=%d, n=%d, %d", x, n, pow(x, n)); 
    return 0; 
}
</textarea></div><p><strong>Output:</strong></p><div class="codeblock3"><pre>
The output for x^n, where x=6, n=3, 216
</pre></div><hr/><h2 class="h3">7) Write code to check a binary tree is BST tree or not?</h2><div class="codeblock"><textarea class="java" name="code">public class CheckBST {
	public static Node prevNode = null;
//Method1:
	public boolean isBST1(Node root) {
		if (root != null) {
			if (!isBST1(root.left))
				return false;
			if (prevNode != null &amp;&amp; prevNode.data &gt;= root.data) {
				return false;
			}
			prevNode = root;
			return isBST1(root.right);
		}
		return true;
	}

	//method 2
	
	public boolean isBST2(Node root, int min, int max) {
		if (root != null) {
			if (root.data &gt; max || root.data &lt; min) {
				return false;
			}
			return isBST2(root.left, min, root.data)
					&amp;&amp; isBST2(root.right, root.data, max);
		} else {
			return true;
		}
	}

	public void inorder(Node root) {
		if (root != null) {
			inorder(root.left);
			System.out.print("  " + root.data);
			inorder(root.right);
		}
	}

	public static void main(String args[]) {
		CheckBST cb = new CheckBST();
		Node root = new Node(7);
		root.left = new Node(3);
		root.right = new Node(9);
		root.left.left = new Node(1);
		root.left.right = new Node(4);
		root.right.left = new Node(8);
		root.right.right = new Node(10);
		System.out.println("Input Tree is ");
		cb.inorder(root);
		System.out.println();
		System.out.println("Tree is BST or not  : " + cb.isBST1(root));
		System.out.println("Tree is BST or not : "
				+ cb.isBST2(root, Integer.MIN_VALUE, Integer.MAX_VALUE));
		root.left.right.right = new Node(20);
		System.out.println("Input Tree is ");
		cb.inorder(root);
		System.out.println();
		System.out.println("Tree is BST or not: " + cb.isBST1(root));
		System.out.println("Tree is BST or not : "
				+ cb.isBST2(root, Integer.MIN_VALUE, Integer.MAX_VALUE));

	}

}

class Node {
	int data;
	Node left;
	Node right;

	public Node(int data) {
		this.data = data;
		left = null;
		right = null;
	}
}
</textarea></div><p><strong>Output:</strong></p><div class="codeblock3"><pre>
Input Tree is 
 1  3  4  7  8  9  10
Tree is BST or not: true
Tree is BST or not: true
Input Tree is 
 1  3  4  20  7  8  9  10
Tree is BST or not: false
Tree is BST or not: false
</pre></div><hr/><h2 class="h3">8) Write a code to find the nth element from the end in a list?</h2><div class="codeblock"><textarea class="java" name="code">public class ListElement{
 
	Node head;
 
	static class Node {
	int value;
	Node next;
 
	Node(int value) {
		this.value = value;
                      }
	}
 
	public void addToList(Node node) {
 
		if (head == null) {
			head = node;
		} else {
			Node temp = head;
			while (temp.next != null)
				temp = temp.next;
 
			temp.next = node;
		}
	}
 
 
	public void printList() {
		Node temp = head;
		while (temp != null) {
			System.out.format("%d ", temp.value);
			temp = temp.next;
		}
		System.out.println();
	}
 
 
	public Node nthFromLastNode(Node head,int n)
	{
		Node firstPtr=head;
		Node secondPtr=head;
 
		for (int i = 0; i &lt; n; i++) {
			firstPtr=firstPtr.next;
 
		}
 
		while(firstPtr!=null)
		{
			firstPtr=firstPtr.next;
			secondPtr=secondPtr.next;
		}
 
		return secondPtr;
	}
 
	public static void main(String[] args) {
		ListElement li = new ListElement();
		// Creating a linked list
		Node head=new Node(18);
		li.addToList(head);
		li.addToList(new Node(20));
		li.addToList(new Node(30));
		li.addToList(new Node(15));
		li.addToList(new Node(10));
 	    li.addToList(new Node(16));
		li.printList();
		Node nthNodeFromLast= li.nthFromLastNode(head,4);
		System.out.println("4th node from end is :"+ nthNodeFromLast.value);
 
	}
 
}
</textarea></div><p><strong>Output:</strong></p><div class="codeblock3"><pre>
18 20 30 15 10 16 
4th node from end is: 30
</pre></div><hr/><h2 class="h2 center">Technical Round interview questions:</h2><hr/><p>This is the third main round of the Adobe interview process. It contains various rounds. In this round, candidates are checked on their technical skills. If candidate clears one round, then he/she can proceed for the next round.</p><h2 class="h2">Technical First round</h2><h2 class="h3">1) Differentiate between typedef and #define?</h2><p class="pq">The primary difference between typedef and #define is given below:</p><ol class="pointsa"><li>typedef is used to define the types or to give a new name to types whereas #define is pre-processor directive, which is used to define the macro.</li><li>typedef gives the actual definition to the new datatype, whereas #define is used just to copy-paste the value definition where it is used.</li><li>typedef is known to the compiler, but #define is just known to pre-processor.</li></ol><p><strong>Example:</strong></p><div class="codeblock"><textarea class="cpp" name="code">#include &lt;stdio.h&gt; 
typedef int CHAR; 
#define AP "Andhra Pradesh"

int main() 
{ 
	CHAR a, b; 
	a = 10; 
	printf("%d\n""%s"  , a, AP); 
	return 0; 
}
</textarea></div><p><strong>Output:</strong></p><div class="codeblock3"><pre>
10
Andhra Pradesh
</pre></div><hr/><h2 class="h3">2) Why we use sprint() function?</h2><p>sprint() is a C library function which is termed as "string print." sprintf function is used to hold the formatted data output as String.</p><p><strong>Syntax:</strong></p><div class="codeblock"><textarea class="cpp" name="code">int  sprintf (char *string,  const char *form, .... )
</textarea></div><p><strong>Example:</strong></p><div class="codeblock"><textarea class="cpp" name="code">#include&lt;stdio.h&gt; 
int main() 
{ 
	char string[50]; 
	int a = 10, b = 5, c; 
	c = a * b; 
	sprintf(string, "multiplication of %d and %d is %d", a, b, c); 
           	printf("%s",  string); 
return 0; 
}
</textarea></div><p><strong>Output:</strong></p><div class="codeblock3"><pre>
multiplication of 10 and 5 is 2
</pre></div><hr/><h2 class="h3">3) How to differentiate between char a[]= ?String and char*a =?String.</h2><p>The statements:</p><ol class="points"><li>Char a[ ]= "computer";</li><li>char *a= "computer";</li></ol><p>The difference between the above two statements is that the first statement will create an array of 9 elements will automatically add the null pointer and the size of array 'a' will be 9.</p><p>But the second statement will create a pointer variable. We cannot perform any array operation on this pointer variable as it will be stored in read-only mode.</p><p><strong>Example:</strong></p><div class="codeblock"><textarea class="cpp" name="code">#include &lt;stdio.h&gt; 
int main() 
{ 
	char a[] = "Computer"; 
	printf("%lu", sizeof(a)); 
	a[1] = 'n'; 
	printf("\n%s", a); 
	return 0; 
}    
</textarea></div><p><strong>Output:</strong></p><div class="codeblock3"><pre>
9
Cnmputer
</pre></div><p><strong>Example 2</strong></p><div class="codeblock"><textarea class="cpp" name="code">#include &lt;stdio.h&gt; 
int main() 
{ 
	char *a = "Computer"; 
	printf("%lu", sizeof(a)); 

	return 0; 
}
</textarea></div><hr/><h2 class="h3">4) Explain Data breakpoints? Where can we use this?</h2><p>Data Breakpoint is a strong feature available for C++, which allow us to stop the execution when the value stored at a particular memory location changes. Data breakpoints can be used to solve the memory corruption issue.</p><hr/><h2 class="h3">5) Differentiate between new and malloc()?</h2><p>The new and malloc() both are used for dynamic memory allocation. But there are various differences between new and malloc, which are given below,</p><ul class="points"><li>new is an operator in C language, whereas malloc() is a function for memory allocation.</li><li>new operator calls the constructor, whereas malloc() does not call the constructor.</li><li>The memory allocated from the "<strong>free store</strong>" by new operator, whereas memory allocated from the heap by malloc() function.</li><li>On failure of execution, new operator throws an exception, whereas malloc() returns Null.</li><li>new operator does not require the sizeof() operator, malloc() function requires the sizeof() operator to know the memory size.</li></ul><hr/><h2 class="h3">6) Differentiate between process and thread?</h2><p>Following are the basic differences between the process and the thread:</p><ul class="points"><li>The Process is an execution of a program, whereas thread is a lightweight process.</li><li>A Process does not share the resources like memory, whereas thread can share the resources.</li><li>The Process takes more time for context switching, whereas thread requires less time for context switching.</li><li>The Process is less efficient as compared to a thread in terms of communication.</li></ul><hr/><h2 class="h3">7) What is C++ Shorthand property? What is its role?</h2><p>C++ provides shorthand property, which enables a programmer to use the assignment operator in a shorter way.</p><p><strong>Example:</strong></p><p>x=x+5; can be written as x+=5 using shorthand</p><p>x=x-10; can be written as x-=10;</p><hr/><h2 class="h3">8) What do you understand by function prototype declaration and definition?</h2><p><strong>Function prototype declaration</strong>: function prototype declaration statement gives the following information about the function:</p><ol class="points"><li>It tells the symbolic name of the functions.</li><li>Information about the return type of function.</li><li>Information about the argument passed as input with their datatypes.</li></ol><p><strong>Example</strong>:</p><div class="codeblock"><textarea class="cpp" name="code">int add(int a, int b, int c)
</textarea></div><p>Where add is the name of a function, and a, b and c are the passed arguments.</p><p><strong>Function definition</strong>: The function definition is the actual source code of the function. Function definition gives information that what that function actually does.</p><p><strong>Example:</strong></p><div class="codeblock"><textarea class="cpp" name="code">int add(int a, int b, int c){&lt;br&gt;
c= a + b;
return c;
}
</textarea></div><hr/><h2 class="h3">9) What do you understand by Conditional Operators?</h2><ul class="points"><li><strong>Conditional operators</strong> are ternary operators with three operands, which are used as shorthand in place of the if-else statement.</li><li>Conditional operators return the first expression if the condition is true and return second expression if the condition is false.</li></ul><p><strong>Syntax:</strong></p><div class="codeblock"><textarea class="java" name="code">(Check expression)? Expression1: Expression2;
</textarea></div><p><strong>Example:</strong></p><div class="codeblock"><textarea class="java" name="code">var = (x &lt; 10) ? 20 : 40;
</textarea></div><hr/><h2 class="h3">10) What is volatile Keyword in C?</h2><p>The volatile keyword is a qualifier which is used with the variables at the time of declaration.</p><p>It gives the information to the compiler that variable's value can be changed at any instance of time even it does not appear to be modified.</p><p>Volatile keyword is used to declare a variable as a volatile variable. It can be used before the datatype or after the data type.</p><p><strong>Syntax:</strong></p><div class="codeblock"><textarea class="java" name="code">volatile int x;   or int volatile x; 
</textarea></div><hr/><h2 class="h3">11) What do you understand by OS? Explain in Easiest way.</h2><ul class="points"><li>An operating system is a program which is an interface between the user and hardware</li><li>It manages all other programs in the computer after loaded, by a boot program.</li><li>OS works as a backbone for the computer or mobile devices.</li><li>Examples of an operating system are UNIX, LINUX, MS- Windows, MAC-OS, etc.</li></ul><hr/><h2 class="h3">12) Why we use pointers in C and C++?</h2><p>Pointers are the variables which stores address of another variable in C and C++.</p><p>Following are the main reasons that why we use pointers in C and C++:</p><ul class="points"><li>Pointers can be used for dynamic memory allocation.</li><li>Pointers help to perform array arithmetic and accessing an array element.</li><li>Pointers are helpful in creating API.</li><li>Pointers are used in the implementation of the data structure.</li><li>Pointers are beneficial to pass by reference.</li></ul><hr/><h2 class="h3">13) Differentiate between call by pointer and call by reference?</h2><p>In C++ language, we can pass an argument to a function by reference or by pointer, both are the correct approaches and precisely same, but the basic differences between both are:</p><ul class="points"><li>We can assign pointer as a null pointer directly, but it cannot be done with reference.</li><li>We can reassign a pointer, but reference cannot be reassigned.</li></ul><hr/><h2 class="h3">14) What do you understand by calloc() and malloc()?</h2><p>In C, calloc() and malloc() are the library functions, and both are used for dynamic memory allocation. Which means it allocates the memory at run-time as per requirement from the heap section.</p><p><strong>malloc()</strong>: malloc() function is a library function which allocates a single block of requested memory and return a pointer void to it, which can be cast to any return type. It returns the null value if sufficient memory is not available.</p><p><strong>Syntax:</strong></p><div class="codeblock"><textarea class="java" name="code">ptr=(cast-type*)malloc(byte-size)
</textarea></div><p><strong>calloc()</strong>: calloc() function is also a library function which allocates the multiple blocks of memory of requested size. It initially initializes the memory to zero and returns NULL if memory is not sufficient.</p><p><strong>Syntax:</strong></p><div class="codeblock"><textarea class="java" name="code">ptr=(cast-type*)calloc(number, byte-size)
</textarea></div><hr/><h2 class="h3">15) Explain the term, "virtual machine"?</h2><p>The Virtual machine is a software program which behaves like a separate computer. It works same as the main computer and also capable of running applications and other programs. A virtual machine, called as a guest is created within the main machine called as host. There are two types of virtual machines depending upon their uses.</p><ol class="pointsa"><li>System virtual machine</li><li>Process virtual machine</li></ol><hr/><h2 class="h3">16) What do you understand by Synchronization?</h2><p><strong>Synchronization</strong> is a process of performing two things simultaneously at the same time.</p><p><strong>Synchronization is of two types:</strong></p><ul class="points"><li>Process or thread synchronization</li><li>Data synchronization</li></ul><p><strong>Process synchronization</strong>: Process/thread synchronization is a mechanism which controls the access of shared resources between two concurrent threads. It ensures that two concurrent thread do not share the same resource at the same time. Synchronization deals with problems such as deadlock, starvation, busy waiting, etc.</p><p><strong>Data Synchronization</strong>: Data synchronization is a technique which ensure the integrity of data between two devices. With the help of data synchronization, it keeps multiple copies of single data in different location. It includes file synchronization, journaling, Raid, etc.</p><hr/><h2 class="h3">17) Explain the term Mutex? What is Reader-writer problem?</h2><p><strong>Mutex:</strong></p><ul class="points"><li>In multithreading, <strong>Mutex(mutual exclusion object)</strong> is a program object which provides locking mechanism to the threads.</li><li>Mutex ensures the proper thread synchronization between two or more threads. Only one thread can execute a program or resources at a time.</li></ul><p>Reader-writer problem:</p><p>In OS, a situation is called as Reader-writer problem for a particular shared data area which involves:</p><ul class="points"><li>Any number of reader can read from that shared area, but only one writer can write at one time.</li><li>No other process can access that area when one writer is writing in that particular area.</li><li>If in that shared area there are non-zero readers then writer cannot write there.</li></ul><p>This problem mostly occurs in Concurrency or multithreading.</p><hr/><h2 class="h3">18) Why we use void keyword?</h2><p>We can use void keyword for two purposes:</p><p><strong>Function parameter</strong>: When we use void as function parameter, it means function does not accept any value.</p><p><strong>Example:</strong></p><div class="codeblock"><textarea class="cpp" name="code">int showMessage(void){   
}
</textarea></div><p><strong>Function Return type</strong>: When we use void as function return type, it means it will not return anything.</p><p><strong>Example:</strong></p><div class="codeblock"><textarea class="cpp" name="code">void showMessage() {
} 
</textarea></div><p>void keyword can also be used with the pointers which makes it more powerful as, when void is used with pointer it termed as generic type, which can hold address of any type.</p><hr/><h2 class="h3">19) Explain the exit controlled loop?</h2><p>An Exit controlled loop is a type of loop which first execute the instruction and then checks the condition. When we use exit controlled loop, then at least one time execution occurs even if the condition is false. The do-while loop is an example of exit controlled loop.</p><div class="codeblock"><textarea class="cpp" name="code">#include &lt;stdio.h&gt;

int main() {
int x = 10; 
do{
    printf("\n the value of x is %d", x);
    x - -;
}
while(x&gt;=5);
   return 0; 
}

Output: 
the value of x is 10
 the value of x is 9
 the value of x is 8
 the value of x is 7
 the value of x is 6
 the value of x is 5
</textarea></div><hr/><h2 class="h3">20) What is a DNS server?</h2><p>DNS server is a main part of <strong>DNS (Domain Name System)</strong> infrastructure. It is a computer server which stores and manages the database of IP addresses and their respective Hosts name.</p><p>DNS server is also called as name server, which is used to map the domain name to the corresponding IP address.</p><p>A single domain name can have multiple IP's that means IP addresses can vary with time.</p><img alt="Adobe Interview Questions" src="https://images.tpointtech.com/interview/images/adobe-interview-questions.png"><hr/><h2 class="h2">Technical Second Round</h2><h2 class="h3">1) What are the different layers in TCP/IP models? Explain the protocols at each layer?</h2><p><strong>TCP/IP model</strong> is termed as <strong>Transmission Control Protocol/Internet Protocol</strong>. TCP/IP model is a practical and concise version of the OSI model. Current network architecture depends on the TCP/IP model. It consists of mainly four layers:</p><ul class="points"><li>Application Layer</li><li>Transport Layer/Host-to-host layer</li><li>Network Layer</li><li>Link Layer/Network Access Layer</li></ul><p><strong>1. Link Layer:</strong></p><p>is responsible for the physical flow of data through the network. It consists of hardware devices such as optical fibre, coaxial cable, or twisted pair, etc. In this layer, data travels in the form of bits and frames.</p><p>The protocol used at this level is Ethernet, token ring, etc.</p><p><strong>2. Internet Layer:</strong></p><p>Internet layer is the Upper layer of the Link layer. This layer converts the data into data-packets, called as IP datagrams and send these datagrams across the host through the network. These datagrams consist of host and destination address, by which they are forwarded through the network.</p><p>The primary protocols used at this level are:</p><ul class="points"><li><strong>IP (internet protocol)</strong>: This protocol is responsible for forwarding the packets from source host to destination using an address which is consisted by packet header. IP has two main versions IPv4 and IPv6.</li><li><strong>ICMP (Internet control message protocol)</strong>: This protocol is mainly responsible for informing the problem in the network.</li><li><strong>ARP (Address resolution protocol)</strong>: ARP protocol is an essential protocol of the TCP/IP model, and it is responsible to resolve an IPv4 address to physical address.</li></ul><p><strong>3. Transport Layer</strong>: This is the third layer of the TCP/IP model, which is responsible for the communication between the source host and destination host and error-free data transmission.</p><p><strong>This layer consists of mainly two protocols:</strong></p><p><strong>TCP (Transmission Control Protocol)</strong>: TCP is a reliable protocol for error-free communication between the source and destination host. It's a connection-oriented protocol.</p><p><strong>UDP (User Datagram Protocol)</strong>: This protocol is not reliable as compare to TCP protocol, we can use this protocol which does not require reliable communication. It is a connectionless protocol.</p><p><strong>4. Application layer</strong>: This is the top layer of the TCP/IP model. It describes the application protocol and provides node-to-node communication.</p><p>This layer contains various higher level protocols which are:</p><ul class="points"><li>HTTP and HTTPs(Hypertext transfer protocol)</li><li>FTP(File transfer protocol)</li><li>SSH( Secure Shell)</li><li>TFTP(Trivial file transfer protocol)</li><li>SMTP(Simple mail transfer protocol)</li><li>DHCP(Dynamic host configuration protocol)</li></ul><hr/><h2 class="h3">2) Explain the working of the stack while calling a function? When stack overflow occurred?</h2><p>The Stack is a particular area of RAM, just like as Heap. But stack is used to store local variables, parameters and return values used inside a function and stack stores and deallocates memory automatically.</p><p><strong>When we call a function, stack performs following steps:</strong></p><ul class="points"><li>Push space for the return variables.</li><li>Push parameters in the stack.</li><li>Push the local variable of the function.</li></ul><p>When we call a function, stack adds a stack frame which consists space for actual parameters, local variables, return address, etc. This stack frame lives in active frame till the time function is being called, and once execution finishes then stack remove that stack frame from the stack.</p><p><strong>Stack Overflow</strong>: As we know that stack deallocated the memory and free up space after execution but still there is a condition when complete stack space used, and there is no more space to save the variables, so this is called stack overflow. It occurs because the space size of the stack is also limited in size, and at the time of execution if we allocate more memory than available memory than overflow occurred and the program got crashed. Some example for stack overflow are:</p><ul class="points"><li>Use of Infinite recursion</li><li>Use of very large stack variable</li><li>Use of very deep recursion</li></ul><hr/><h2 class="h3">3) Explain the meaning for the declaration: int*const p &amp; const int* const p?</h2><p><strong>int * const p</strong>: By declaring a pointer in such a way that means we are declaring point variable p as constant, which cannot be changed. We cannot change the address its holding, or it cannot point to other variables. If we try to change the address of p, then it will give a compile time error.</p><p><strong>const int * const p</strong>: By declaring a pointer in such a way means, we cannot change the address of the pointer as we as we cannot change the address at that address. If we try to do it, then it will generate a compile time error.</p><hr/><h2 class="h3">4) What are default functions in C++</h2><p class="pq">C++ provides the six default member functions which are given below:</p><ul class="points"><li>Default constructor</li><li>Destructors</li><li>Copy constructors</li><li>Copy assignment operators</li><li>Move constructors</li><li>Move assignment operators</li></ul><hr/><h2 class="h3">5) Which data structure is used for the dictionary?</h2><p>To implement a dictionary, which type of data structure should be used depends on what we required, there are some following data structure which can be used for implementation of the dictionary.</p><p><strong>Hash-table</strong>: If we want a simple dictionary with no option for the prefix, or nearest neighbour search then we can use Hashing or Hashtable for the dictionary.</p><p><strong>Trie</strong>: It can be a good option if we want to add prefix and fast lookup. But, it takes more space than other data structures.</p><p><strong>Ternary Search Tree</strong>: If we want all the qualities like trie but do not want to give the more space then we can use ternary search tree.</p><p><strong>BK-tree</strong>: BK-tree is one of the best data structure if we want specifications like spell checker, find the similar word, etc.</p><hr/><h2 class="h3">6) How can you find a unique word from a String which also has duplicate words?</h2><p>We can find the unique word from a string by using HashMap, Set and Regex.</p><p><strong>Candidate can also be asked for questions like:</strong></p><ol class="points"><li>Implement Snake and Ladder game and find the minimum number of moves required to reach from 1 to 100 in a given game, using Dynamic Programming.</li><li>Model a data structure for a DFA that takes an event as parameter and performs a desired action.</li><li>Solve the three mislabelled jars problem.</li><li>How to compare two binary trees?</li><li>How to prove that in a tree the number of internal nodes is one less than leaves?</li></ol><hr/><h2 class="h2 center">Technical third round or director Round</h2><hr/><p>This round is a challenging round as in this round the manager ask the questions based on your projects, so candidate must have in-depth knowledge about their project which they have done and some problematic puzzles which candidates needs to solve.</p><h2 class="h3">1) Write an algorithm for the tower of Hanoi?</h2><p>Tower of Hanoi is a very popular mathematics puzzle. In this puzzle, we are given three disk and three rods. Disks are arranged in the first rod like a stack, in ascending order. We need to transfer the disk from the first rod to third in the same order.</p><p><strong>There are some rules as well:</strong></p><ul class="points"><li>We can move one disk at one time</li><li>We can only move the uppermost disk</li><li>Disk always should be in ascending order, i.e., a bigger disk cannot put on a smaller one.</li></ul><p><strong>Algorithm:</strong></p><p>Let's suppose there are thee towers Beg, Aux, and Dest, and there are two disks where n disk is larger disk and n-1 is smaller one.</p><p><strong>Start</strong></p><p><strong>Step 1</strong>: shift n-1 disk from tower Beg to Aux</p><p><strong>Step 2</strong>: shift n disk from Beg to End</p><p><strong>Step 3</strong>: shift disk n-1 form tower Aux to C.</p><div class="codeblock"><textarea class="java" name="code">Tower(n, Beg, Aux, Dest)
Begin
If n=1 then,
Print: Beg-&gt; Dest;
else
 Call Tower(n-1, Beg, Dest, Aux);
Call Tower(n, Beg, Aux, End);
Call Tower(n-1, Aux, Beg, End);
endif
End
</textarea></div><hr/><h2 class="h3">2) Write a code to find the loop in a Linked list? How will you remove this loop?</h2><div class="codeblock"><textarea class="cpp" name="code">#include&lt;stdio.h&gt; 
#include&lt;stdlib.h&gt; 
struct Node 
{ 
	int data; 
	struct Node* next; 
}; 

/* Function for removing the loop. */
void remLoop(struct Node *, struct Node *); 

/*Function to remove and detect the loop*/
int detAndRemLoop(struct Node *list) 
{ 
	struct Node *p1 = list, *p2 = list; 

	while (p1 &amp;&amp; p2 &amp;&amp; p2-&gt;next) 
	{ 
		p1 = p1-&gt;next; 
		p2 = p2-&gt;next-&gt;next; 

		/*if p1 and p2 will meet at some point which means there is a loop*/
		if (p1 == p2) 
		{ 
			remLoop(p1, list); 
	                           printf("Loop is occurred\n"); 
			/* Return 1 if loop is found */
			return 1; 
		
		} 
	} 

	/* Return 0 if there is no loop*/
	return 0; 
} 

/* Function to remove loop. */
void remLoop(struct Node *loop_node, struct Node *head) 
{ 
	struct Node *ptr1 = loop_node; 
	struct Node *ptr2 = loop_node; 

	// Count the number of nodes in loop 
	unsigned int k = 1, i; 
	while (ptr1-&gt;next != ptr2) 
	{ 
		ptr1 = ptr1-&gt;next; 
		k++; 
	} 

	// Fix one pointer to head 
	ptr1 = head; 
	ptr2 = head; 
	for (i = 0; i &lt; k; i++) 
	ptr2 = ptr2-&gt;next; 
	while (ptr2 != ptr1) 
	{ 
		ptr1 = ptr1-&gt;next; 
		ptr2 = ptr2-&gt;next; 
	} 
	ptr2 = ptr2-&gt;next; 
	while (ptr2-&gt;next != ptr1) 
	ptr2 = ptr2-&gt;next; 

	/* Set the next node to Null to fix the loop */
	ptr2-&gt;next = NULL; 
} 

/* Function to print linked list */
void printList(struct Node *node) 
{ 
	while (node != NULL) 
	{ 
		printf("%d ", node-&gt;data); 
		node = node-&gt;next; 
	} 
} 

struct Node *newNode(int key) 
{ 
	struct Node *temp = (struct Node*)malloc(sizeof(struct Node)); 
	temp-&gt;data = key; 
	temp-&gt;next = NULL; 
	return temp; 
} 

int main() 
{ 
	struct Node *head = newNode(40); 
	head-&gt;next = newNode(15); 
	head-&gt;next-&gt;next = newNode(12); 
	head-&gt;next-&gt;next-&gt;next = newNode(10); 
	head-&gt;next-&gt;next-&gt;next-&gt;next = newNode(4); 

	/* Create a loop*/
	head-&gt;next-&gt;next-&gt;next-&gt;next-&gt;next = head-&gt;next-&gt;next; 

	detAndRemLoop(head); 

	printf("Linked List after removing loop \n"); 
	printList(head); 
	return 0; 
}
</textarea></div><p><strong>Output:</strong></p><div class="codeblock3"><pre>
Loop is occurred
Linked List after removing loop 
40 15 12 10 4
</pre></div><hr/><h2 class="h3">3) How will you design a data structure for excel spreadsheets?</h2><p>We can design an excel spreadsheets by using:</p><ul class="points"><li>Two-dimensional array ( but it will take lots of space)</li><li>Sparse matrix</li><li>Map, etc.</li></ul><hr/><h2 class="h3">4) Explain memory protection in OS.</h2><p>Memory protection is a mechanism which controls the unauthorized access of memory in the computer. Memory protection prevents the unallocated memory access by a process. Memory address is first checked before used by a process, to see whether it is allocated address or not.</p><p>There are two registers LBR and UBR are used to implement memory protection.</p><hr/><h2 class="h3">5) What is Virtual Memory in OS?</h2><p><strong>Virtual Memory is memory management technique</strong> of Operating System. Virtual memory is an extra space provided to a program when a main memory does not have the sufficient space to execute a code. It temporarily transfers data from RAM to disk storage, which uses inactive memory of hard disk, which is termed as Virtual Memory.</p><hr/><h2 class="h3">6) Write an algorithm to insert an element into a sorted linked list?</h2><p>Suppose the linked list is sorted in ascending order then following is the algorithm for the same. Let the input node is 13 and let assign as n</p><p><strong>Suppose Input linked list is</strong>:</p><div class="codeblock"><textarea class="java" name="code">3 8 11 15 20 
</textarea></div><p>1) If given linked list is empty then assign the node as head and return it.</p><p>2) If value of the node n is less than value of head node, then insert the node at start and assign it as head.</p><p>3) In a loop, search the appropriate node after which the input node is to be inserted. To search the appropriate node start from head, keep moving until you reach a node x(Let?s suppose 15)whose value is greater than the input node. The node before the x will be the appropriate node(11).</p><p>4) Insert the node(13) after the appropriate node(11) found in step 3.</p><p><strong>After insertion:</strong></p><div class="codeblock"><textarea class="java" name="code">3 8 11 13 15 20 
</textarea></div><hr/><h2 class="h3">7) Find pair of elements whose sum equal to a given number?</h2><div class="codeblock"><textarea class="cpp" name="code">#include &lt;stdio.h&gt;

void Pair(int arr[], int n, int sum)
{
    for (int i = 0; i &lt;=n; i++)
    {
        for (int j = i + 1; j &lt;=n; j++)
        {
            if (arr[i] + arr[j] == sum){
            
                printf("Pair element found at position %d and %d\n ", i, j);}
            
        }
    }
}
 

int main()
{
    int arr[] = { 5,8,9,1,6,2,7,3};
    int sum = 11;
 
    int n = sizeof(arr)/sizeof(arr[0]);
 
    Pair(arr, n, sum);
 
    return 0;
}
</textarea></div><p><strong>Output:</strong></p><div class="codeblock3"><pre>
Pair element found at position 0 and 4
 Pair element found at position 1 and 7
 Pair element found at position 2 and 5
</pre></div><hr/><h2 class="h3">Candidates can also be asked for following questions:</h2><ol class="points"><li>If there is an array of number which contains numbers from 1 to n. If we replace 1 number with another. Find both number in O (N).</li><li>If in a marriage function there are n people then arrange those people in two groups, such that each person know each other?</li><li>Implement Snake and Ladder game and find the minimum number of moves required to reach from 1 to 100 in a given game, using Dynamic Programming.</li><li>There are n houses in a city. All in a single row. We can colour a house with any one of three colours (R,G,B). Cost of colouring each house is given for each colour. No two neighbour house can have same colour. Print min cost to colour all house.</li><li>If Given LinkedList and a number k. reverse LinkedList in a group of k.</li></ol><hr/><h2 class="h2 center">HR Round</h2><hr/><p>HR round will be the last round for the complete recruitment process. This will be an easy round as compare to all above rounds as in this round, interviewer just wants to interact with the candidate. In this round, interviewer will judge the candidate on the basis of communication skills and soft skills.</p><h2 class="h3">1) Brief about yourself?</h2><p>This question is a very common question and asked mostly in most of the interviews. Answer of this question should be in the following way.</p><blockquote><p>Good morning/afternoon/evening, sir/mam, it's my pleasure to have this opportunity for introducing myself. My name is Anamika Singh, and I belong to Udaipur. I have completed my B. Tech in CSE branch from Noida Institute of Engineering &amp; technology, and I did my schooling from Saint John Inter College.</p><p>If I talk about my family member, so there are 5 members in my family including me. My father is a Government teacher, my mother is a housewife, and I have a younger brother who has completed his higher secondary last month.</p><p>I am having a good knowledge of programming languages such as C, C++, and Java. I have also created some college-based project on these technologies.</p><p>I am very Confident, smart and adaptive person. I can adjust myself in any environment and can deal with any type of situation.</p><p>My hobbies are playing badminton, dancing, painting, and internet surfing.</p><p>Thank you.</p></blockquote><hr/><h2 class="h3">2) Why do you want to join Adobe?</h2><p>The interviewer asks this question to check if you are really interested to join or what is your motivation to join this company. You should answer this question in the following way:</p><blockquote><p>Sir, Adobe is one of the great companies, which spread over world-wide. Everyone would love to work with Adobe. It's a great place to work. And my technical skills match with the company' requirement. I can show my technical skills to contribute for company's growth as well as my career growth.</p></blockquote><hr/><h2 class="h3">3) What skills do you have, so that we should hire you?</h2><p>By this question, interviewer wants to check, that how deep you know about your skills and how see yourself differently from others. Answer for this should be given as:</p><blockquote><p>I have a good theoretical and practical knowledge of C, C++, Java, and Data structure. I have created various projects on these technologies. I can solve coding puzzles very efficiently in less time than others.</p></blockquote><hr/><h2 class="h3">4) Which is your dream company?</h2><p>By this question, the interviewer wants to check your passion. Is this company is your dream company, or you want to join this company as you don't have any other options. So candidate should answer this question carefully.</p><p>To answer this question candidate should never use any other company's name while they can choose the characteristics of the company.</p><p><strong>Example:</strong></p><p><strong>My dream job is one, which works on innovation and which provides product to the world which can change the one's lifestyle. And I was excited about this job. As per my knowledge, Adobe is a company which beliefs on the innovation and creativity.</strong></p><hr/><h2 class="h3">5) Tell something about your family background?</h2><p>This is a general and relaxing question as you don't need to think so much to answer this. To answer this question, you need to tell how many members do you have, and what they do.</p><p><strong>Example:</strong></p><blockquote><p>There are five members in my family including me. My father Mr. Jay Prakash is a Businessman, having a business of Electronics equipment. My mother Mrs. Sunita is a great homemaker. I have two Elder brothers, who are working in HCL technologies as software developers.</p></blockquote><hr/><h2 class="h3">6) Where do you want to see yourself after ten years?</h2><p><strong>Example:</strong></p><blockquote><p>After ten years, I want to see myself on a respective position in this company where I can handle big responsibilities of the company. I want to learn on every level which will enhance my skills, and it will be helpful for the company growth.</p></blockquote><hr/><h2 class="h3">7) What is your unique and different quality, which makes you the most suitable employee for this company?</h2><p>This is the same question as "why should I hire you," Answer should be given as question number 3.</p><hr/><h2 class="h3">8) Do you think that you are a goal oriented person?</h2><blockquote><p>Yes, I am a goal-oriented person, I have some key goal of life which I want to achieve as early as I can. I regularly update my goal list that till the time what I Have achieved, and what is remaining yet.</p></blockquote><hr/><h2 class="h3">9) What are your greatest strength and Weakness?</h2><p>My greatest strength is my self-motivated nature. With the help of this, I can face any challenge.</p><p>My greatest weakness is my emotional nature. I get susceptible when I see someone in any adverse condition.</p><br/> </img></td></tr></tbody></table></div><br/></div><div class="related-posts-container"><h2 class="h3">Related Posts</h2><ul class="related-posts-list"><li><a class="related-post-item" href="intuit-interview-questions"><h3 class="h3">Intuit Interview Questions | Intuit Recruitment Process (2025)</h3><p class="related-post-content">Intuit Recruitment Process About Company Intuit Inc. is a business and financial Software Company that creates and offers monetary, bookkeeping and duty planning programming and related administrations for small businesses, accountants and people. The organization was established in 1983, headquartered in Mountain View, California. Notwithstanding the United States, the organization...</p><p class="reading-time"><i aria-hidden="true" class="fa fa-clock-o"></i> 19 min read <span class="arrow-position"><svg fill="currentColor" height="1.3rem" stroke="currentColor" stroke-width="0" viewbox="0 0 512 512" width="1.3rem" xmlns="http://www.w3.org/2000/svg"><path d="M295.6 163.7c-5.1 5-5.1 13.3-.1 18.4l60.8 60.9H124.9c-7.1 0-12.9 5.8-12.9 13s5.8 13 12.9 13h231.3l-60.8 60.9c-5 5.1-4.9 13.3.1 18.4 5.1 5 13.2 5 18.3-.1l82.4-83c1.1-1.2 2-2.5 2.7-4.1.7-1.6 1-3.3 1-5 0-3.4-1.3-6.6-3.7-9.1l-82.4-83c-4.9-5.2-13.1-5.3-18.2-.3z"></path></svg></span></p></a></li><li><a class="related-post-item" href="amazon-interview-questions"><h3 class="h3">Top Most asked Amazon Interview Questions (2025)</h3><p class="related-post-content">Top Most asked Amazon Interview Questions Once the CEO of Amazon, Jeff Bezos said, &amp;quot;I&amp;#39;d rather interview 50 people and not hire anyone than hire the wrong person.&amp;quot; You can understand the quality of the recruitment process of Amazon by the statement of their CEO. It doesn&amp;#39;t mean Amazon wants...</p><p class="reading-time"><i aria-hidden="true" class="fa fa-clock-o"></i> 17 min read <span class="arrow-position"><svg fill="currentColor" height="1.3rem" stroke="currentColor" stroke-width="0" viewbox="0 0 